"""Lesson content. To add a lesson, append another dict to LESSONS (slug must be unique)."""

LEVELS = {1: {"key": "fundamentals", "name": "Fundamentals"}, 2: {"key": "intermediate", "name": "Intermediate"},
          3: {"key": "advanced", "name": "Advanced"}, 4: {"key": "projects", "name": "Real-World Projects"}}
LEVEL_TITLES = {1: "BEGINNER", 2: "INTERMEDIATE", 3: "ADVANCED", 4: "EXPERT"}


def lesson(slug, level, title, topic, intro, explain, syntax, parts, example, use_cases, mistakes,
           ex_prompt, ex_solution, hints, ex_expl, quiz, scenario="school", kind="select", check=None, default_sql=None):
    return dict(slug=slug, level=level, title=title, topic=topic, intro=intro, explain=explain, syntax=syntax,
                parts=parts, example=example, use_cases=use_cases, mistakes=mistakes, scenario=scenario,
                default_sql=default_sql or example,
                exercise=dict(id="L:" + slug, topic=topic, level=level, scenario=scenario, prompt=ex_prompt,
                              solution=ex_solution, kind=kind, check=check, hints=hints, explanation=ex_expl),
                quiz=dict(zip(("q", "options", "answer", "explain"), quiz)))


