LESSON_BY_SLUG = {l["slug"]: l for l in LESSONS}


def neighbors(slug):
    i = next(i for i, l in enumerate(LESSONS) if l["slug"] == slug)
    return (LESSONS[i - 1] if i else None), (LESSONS[i + 1] if i + 1 < len(LESSONS) else None)
